.cpa-modal-head h3 { margin: 0; font-size: 1.15rem; color: var(--cpa-green-dark); }
.cpa-modal-close { background: none; border: none; color: var(--gray-400); cursor: pointer; font-size: 1.1rem; padding: 4px; }
.cpa-modal-close:hover { color: var(--gray-700); }
.cpa-modal-body { padding: 20px 22px; }

.cpa-modal-foot {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 16px 22px;
  border-top: 1px solid var(--gray-200);
}

.cpa-field { display: block; margin-bottom: 14px; }
.cpa-field-label { display: block; font-size: .82rem; font-weight: 600; color: var(--gray-700); margin-bottom: 5px; }
.cpa-field-label small { font-weight: 400; color: var(--gray-400); }

.cpa-field input {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-md);
  font-size: .92rem;
  font-family: inherit;
}
.cpa-field input:focus { outline: none; border-color: var(--cpa-green); box-shadow: 0 0 0 3px rgb(58 124 82 / 12%); }
.cpa-field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.cpa-search-inline { min-width: 0; }
.cpa-search-inline input { padding-left: 36px; }

.cpa-lookup-results { margin-top: 8px; max-height: 230px; overflow-y: auto; }

.cpa-lookup-item {
  padding: 9px 12px;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  margin-bottom: 6px;
  cursor: pointer;
  transition: border-color .12s, background .12s;
}
.cpa-lookup-item:hover { border-color: var(--cpa-green); background: var(--cpa-green-soft); }
.cpa-lookup-item .li-co { font-weight: 600; color: var(--gray-900); font-size: .9rem; }
.cpa-lookup-item .li-meta { font-size: .8rem; color: var(--gray-500); margin-top: 2px; }
.cpa-lookup-hint { font-size: .82rem; color: var(--gray-400); padding: 6px 2px; }

.cpa-divider { text-align: center; margin: 16px 0; position: relative; }
.cpa-divider::before { content: ''; position: absolute; top: 50%; left: 0; right: 0; height: 1px; background: var(--gray-200); }
.cpa-divider span { position: relative; background: var(--color-surface); padding: 0 12px; font-size: .78rem; color: var(--gray-400); text-transform: uppercase; letter-spacing: .04em; }

.cpa-checkline { display: flex; align-items: center; gap: 8px; font-size: .88rem; color: var(--gray-700); cursor: pointer; }
.cpa-checkline input { width: 16px; height: 16px; accent-color: var(--cpa-green); }
.cpa-modal-error { color: var(--red-700); font-size: .85rem; margin-top: 10px; min-height: 1em; }

/* ---- Toast ---- */
.cpa-toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--cpa-green-dark);
  color: var(--color-on-brand);
  padding: 12px 20px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  font-size: .9rem;
  font-weight: 500;
  opacity: 0;
  pointer-events: none;
  transition: opacity .25s, transform .25s;
  z-index: 1100;
  max-width: 90vw;
}
.cpa-toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.cpa-toast.cpa-toast-error { background: var(--red-700); }

@media (width <= 640px) {
  .cpa-field-row { grid-template-columns: 1fr; }
  .cpa-table th.cpa-hide-sm, .cpa-table td.cpa-hide-sm { display: none; }
  .cpa-actions { justify-content: flex-start; }
}

/* ── Tabs + Re-order Requests view ── */
.cpa-tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--gray-200); margin: 0 0 1.25rem; }

.cpa-tab {
  background: none; border: none; border-bottom: 2px solid transparent; margin-bottom: -1px;
  padding: 10px 16px; font-size: .92rem; font-weight: 600; color: var(--gray-500);
  cursor: pointer; font-family: inherit; display: inline-flex; align-items: center; gap: 7px;
  transition: color .15s, border-color .15s;
}
.cpa-tab:hover { color: var(--cpa-green-dark); }
.cpa-tab-active { color: var(--cpa-green-dark); border-bottom-color: var(--cpa-green); }

.cpa-tab-badge {
  background: var(--red-700); color: var(--color-on-brand); font-size: .68rem; font-weight: 700;
  min-width: 17px; height: 17px; padding: 0 5px; border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
}

.cpa-select {
  padding: 9px 12px; border: 1px solid var(--gray-300); border-radius: var(--radius-md);
  font-size: .9rem; font-family: inherit; background: var(--color-surface); color: var(--gray-700); cursor: pointer;
}
.cpa-select:focus { outline: none; border-color: var(--cpa-green); box-shadow: 0 0 0 3px rgb(58 124 82 / 12%); }

.cpa-req-prod { font-weight: 600; color: var(--gray-900); font-size: .9rem; }
.cpa-req-sub { font-size: .82rem; color: var(--gray-500); margin-top: 1px; }
.cpa-req-note { font-size: .82rem; color: var(--gray-600); font-style: italic; margin-top: 3px; }

.cpa-status-select {
  padding: 5px 8px; border: 1px solid var(--gray-300); border-radius: var(--radius-sm);
  font-size: .82rem; font-weight: 600; font-family: inherit; cursor: pointer;
}
.cpa-status-select:focus { outline: none; border-color: var(--cpa-green); box-shadow: 0 0 0 3px rgb(58 124 82 / 12%); }
.cpa-status-new { background: var(--red-50); color: var(--color-ae); border-color: var(--customer-portal-admin-red-tint-2); }
.cpa-status-in-progress { background: var(--store-rush-soft); color: var(--customer-portal-admin-orange); border-color: var(--customer-portal-admin-orange-2); }
.cpa-status-quoted { background: var(--color-floor-tint); color: var(--customer-portal-admin-cyan); border-color: var(--customer-portal-admin-cyan-tint); }
.cpa-status-closed { background: var(--gray-100); color: var(--gray-500); border-color: var(--gray-200); }

/* ── Reward dollars modal (Phase 5) ── */
.cpa-rw-balance { font-size: .95rem; color: var(--gray-700); margin-bottom: 16px; padding: 10px 14px; background: var(--cpa-green-soft); border-radius: var(--radius-md); }
.cpa-rw-balance strong { color: var(--cpa-green-dark); font-size: 1.15rem; }
.cpa-rw-select { width: 100%; }
.cpa-rw-save-btn { width: 100%; justify-content: center; margin-top: 2px; }
.cpa-rw-ledger-head { font-size: .78rem; text-transform: uppercase; letter-spacing: .04em; color: var(--gray-500); font-weight: 600; margin: 20px 0 8px; }
.cpa-rw-ledger { max-height: 240px; overflow-y: auto; }
.cpa-rw-entry { display: flex; align-items: center; gap: 12px; padding: 8px 2px; border-bottom: 1px solid var(--gray-100); }
.cpa-rw-amt { font-weight: 700; font-size: .9rem; min-width: 74px; }
.cpa-rw-amt.pos { color: var(--cpa-green-dark); }
.cpa-rw-amt.neg { color: var(--red-700); }
.cpa-rw-mid { flex: 1; font-size: .88rem; color: var(--gray-800); }
.cpa-rw-meta { font-size: .76rem; color: var(--gray-400); margin-top: 1px; }
.cpa-rw-when { font-size: .78rem; color: var(--gray-400); white-space: nowrap; }
.cpa-rw-empty { color: var(--gray-400); font-size: .85rem; padding: 12px 2px; }

/* Earned-rewards accrual (2026-09-01) */
.cpa-rw-accrual { font-size: .86rem; }
.cpa-rw-acc-hint { margin-top: 8px; line-height: 1.5; }
.cpa-rw-acc-hint code, .cpa-rw-notconf code { background: rgb(0 0 0 / 6%); padding: 0 4px; border-radius: 3px; font-size: .95em; }
.cpa-rw-acc-window { font-weight: 400; text-transform: none; letter-spacing: 0; color: var(--gray-400); }
.cpa-rw-acc-sum { padding: 10px 12px; background: var(--cpa-green-soft); border-radius: var(--radius-md); margin-bottom: 10px; color: var(--gray-700); line-height: 1.5; }
.cpa-rw-acc-sum .pos { color: var(--cpa-green-dark); }
.cpa-rw-acc-sum .neg { color: var(--red-700); }
.cpa-rw-acc-table { width: 100%; border-collapse: collapse; font-size: .82rem; }
.cpa-rw-acc-table th { text-align: left; font-weight: 600; color: var(--gray-500); padding: 6px; border-bottom: 1px solid var(--gray-200); font-size: .72rem; text-transform: uppercase; letter-spacing: .04em; }
.cpa-rw-acc-table td { padding: 6px; border-bottom: 1px solid var(--gray-100); vertical-align: top; }
.cpa-rw-acc-table .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.cpa-rw-acc-table td.pos { color: var(--cpa-green-dark); font-weight: 700; }
.cpa-rw-acc-table summary { cursor: pointer; list-style: none; font-weight: 600; }
.cpa-rw-acc-table summary::-webkit-details-marker { display: none; }
.cpa-rw-acc-lines { margin-top: 4px; font-size: .76rem; color: var(--gray-500); line-height: 1.5; font-weight: 400; }
.cpa-rw-acc-actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-top: 10px; }
.cpa-rw-notconf { padding: 10px 12px; background: var(--store-rush-soft); border: 1px solid var(--customer-portal-admin-yellow); border-radius: var(--radius-md); color: var(--customer-portal-admin-yellow-dark); line-height: 1.55; }

/* Rewards column (2026-09-02): balance chip opens the rewards modal; header button sorts by balance. */
.cpa-rw-cell { white-space: nowrap; }
.cpa-rw-chip { font: inherit; font-weight: 700; font-variant-numeric: tabular-nums; color: var(--cpa-green-dark); background: var(--cpa-green-soft); border: 1px solid var(--customer-portal-admin-green-2); border-radius: 999px; padding: 3px 10px; cursor: pointer; }
.cpa-rw-chip:hover { background: var(--store-green-100); }
.cpa-th-sort { font: inherit; font-weight: inherit; text-transform: inherit; letter-spacing: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; }
.cpa-th-sort i { opacity: .45; font-size: .85em; }
.cpa-th-sort--on, .cpa-th-sort--on i { color: var(--cpa-green-dark); opacity: 1; }

/* Page theme (2026-09-03, dashboard Workspaces): the customer family's navy, matching
   Leads, My Accounts and Customer Portals. Only the dash-shell theme hooks. */
:root { --dash-theme: var(--gray-800); --dash-theme-dark: var(--gray-900); --dash-theme-bg: var(--slate-100); }

/* Phone (≤640px) — 2026-09-05 staff-dashboard sweep: the page measured wider than the
   viewport at 375px and panned sideways. */
@media (width <= 640px) {
    #cpa-filter, .cpa-search-wrap input { width: 100%; max-width: 100%; box-sizing: border-box; }
}

/* 2026-09-05 review: table wrapper + right-aligned head (were inline style=), visible focus,
   keyboard-navigable lookup results, pressed-state "My customers". */
.cpa-table-scroll { overflow-x: auto; }
.cpa-th-right { text-align: right; }

.cpa-btn:focus-visible, .cpa-btn-icon:focus-visible, .cpa-tab:focus-visible, .cpa-rw-chip:focus-visible,
.cpa-th-sort:focus-visible, .cpa-modal-close:focus-visible, .cpa-lookup-item:focus-visible, .dash-error-banner-close:focus-visible {
  outline: 3px solid var(--cpa-green); outline-offset: 2px;
}
.cpa-lookup-item.is-active { border-color: var(--cpa-green); background: var(--cpa-green-soft); }
.cpa-btn-ghost[aria-pressed="true"] { background: var(--cpa-green-soft); color: var(--cpa-green-dark); border-color: var(--cpa-green); }
.cpa-empty .cpa-btn { margin-top: 12px; }
.cpa-lastlogin.cpa-today { color: var(--cpa-green-dark); font-weight: 600; }

@media (width <= 640px) {
  .cpa-tabs { flex-wrap: wrap; }
  .cpa-tab { padding: 8px 10px; font-size: .86rem; }
  .dash-stat-grid { grid-template-columns: 1fr 1fr; }
  .dash-stat-card--accent { grid-column: 1 / -1; }
  .cpa-controls .cpa-btn { flex: 1 1 auto; justify-content: center; }
  .cpa-modal-overlay { padding: 2vh 8px; }
  .cpa-modal-body, .cpa-modal-head, .cpa-modal-foot { padding-left: 14px; padding-right: 14px; }
}

/* jim-mailing-list.css — the owner's ("Jim's") manual prospect list.
   Deliberately oversized & high-contrast: the primary user is 83 and slow on the
   computer. Big type, big targets (>=52px), one column, plain language. All colors
   come from art-hub.css tokens; --art-theme is the single per-page knob (NWCA green). */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue, merged into its
   existing :root. Map them to shared_components/css/tokens.css names when the page is redesigned;
   raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --jim-mailing-list-green-dark: #007a00;
 --art-theme: var(--color-dash-theme); }
/* stylelint-enable color-no-hex */

/* Comfortable reading width, centered. */
.jml-welcome,
.jml-intro,
.jml-form-card,
.jml-list-section { max-width: 880px; margin-left: auto; margin-right: auto; }

/* ---- welcome header (portrait + greeting) ---- */
.jml-welcome { display: flex; align-items: center; gap: var(--space-4); margin-bottom: var(--space-4); }

.jml-portrait {
    width: 64px; height: 64px; border-radius: 50%; object-fit: cover;
    border: 3px solid var(--art-theme); box-shadow: var(--shadow-sm); flex: 0 0 auto;
}
.jml-greeting { font-size: 24px; font-weight: 700; color: var(--gray-900); margin: 0; }

/* ---- view toggle (Your companies / All companies) ---- */
.jml-viewtoggle { display: flex; gap: var(--space-2); margin-bottom: var(--space-5); flex-wrap: wrap; }

.jml-viewbtn {
    font-family: inherit; font-size: 18px; font-weight: 600;
    min-height: 52px; padding: 0 var(--space-6);
    border: 2px solid var(--gray-300); border-radius: var(--radius-pill);
    background: var(--surface-card); color: var(--gray-700);
    cursor: pointer; display: inline-flex; align-items: center; gap: var(--space-2);
}
.jml-viewbtn:hover { border-color: var(--art-theme); color: var(--art-theme); }
.jml-viewbtn.is-active { background: var(--art-theme); border-color: var(--art-theme); color: var(--color-on-brand); }
.jml-view-n { font-size: 15px; font-weight: 600; opacity: .9; }

/* ---- Mailchimp: collapsed staff strip at the bottom ---- */
.jml-mc-details {
    max-width: 880px; margin: var(--space-6) auto 0;
    border: 1px solid var(--gray-200); border-radius: var(--radius-lg); background: var(--surface-card);
}

.jml-mc-summary {
    list-style: none; cursor: pointer; padding: var(--space-4) var(--space-5);
    font-size: 16px; font-weight: 600; color: var(--gray-600);
    display: flex; align-items: center; gap: var(--space-2);
}
.jml-mc-summary::-webkit-details-marker { display: none; }
.jml-mc-summary::after { content: '▾'; margin-left: auto; color: var(--gray-400); font-size: 18px; }
.jml-mc-details[open] .jml-mc-summary::after { content: '▴'; }
.jml-mc-summary i { color: var(--art-theme); }
.jml-mc-summary:hover { color: var(--gray-800); }
.jml-mc-body { padding: 0 var(--space-5) var(--space-5); }
.jml-mc-scope { font-size: 15px; color: var(--gray-600); font-weight: 600; margin: 0 0 var(--space-3); }
.jml-mc-scope:empty { display: none; }
.jml-mc-engaged-btn { border-color: var(--art-theme); color: var(--art-theme); }
.jml-mc-engaged-btn i { color: var(--state-warning); }
.jml-mc-engaged-btn:hover { background: var(--art-theme-light, var(--brand-100)); }

/* ---- intro line ---- */
.jml-intro {
    font-size: 20px;
    line-height: 1.55;
    color: var(--gray-700);
    background: var(--art-theme-light, var(--brand-100));
    border: 1px solid color-mix(in srgb, var(--art-theme) 25%, transparent);
    border-radius: var(--radius-lg);
    padding: var(--space-5) var(--space-6);
    margin-bottom: var(--space-6);
}
.jml-intro strong { color: var(--gray-900); }

/* ---- green "saved!" confirmation ---- */
.jml-ok {
    max-width: 880px;
    margin: 0 auto var(--space-5);
    display: flex;
    align-items: center;
    gap: var(--space-3);
    font-size: 19px;
    font-weight: 600;
    color: var(--state-success);
    background: var(--state-success-bg);
    border: 1px solid color-mix(in srgb, var(--state-success) 35%, transparent);
    border-radius: var(--radius-md);
    padding: var(--space-4) var(--space-5);
}
.jml-ok i { font-size: 22px; }

/* ---- cards ---- */
.jml-card,
.jml-list-section {
    background: var(--surface-card);
    border: 1px solid var(--gray-200);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-md);
    padding: var(--space-8);
    margin-bottom: var(--space-8);
}

.jml-form-title,
.jml-list-title {
    font-size: 26px;
    font-weight: 700;
    color: var(--gray-900);
    margin: 0 0 var(--space-6);
    display: flex;
    align-items: center;
    gap: var(--space-3);
}
.jml-form-title i { color: var(--art-theme); }

/* ---- AI capture card ---- */
.jml-ai-card { border: 2px solid color-mix(in srgb, var(--art-theme) 45%, transparent); }

.jml-ai-title {
    font-size: 24px;
    font-weight: 700;
    color: var(--gray-900);
    margin: 0 0 var(--space-3);
    display: flex;
    align-items: center;
    gap: var(--space-3);
}
.jml-ai-title i { color: var(--art-theme); }
.jml-ai-help { font-size: 18px; line-height: 1.55; color: var(--gray-700); margin: 0 0 var(--space-5); }
.jml-ai-help strong { color: var(--gray-900); }
.jml-ai-label { font-size: 18px; font-weight: 600; color: var(--gray-800); display: block; margin-bottom: var(--space-2); }

.jml-ai-card textarea {
    font-family: inherit;
    font-size: 19px;
    color: var(--gray-900);
    background: var(--surface-card);
    border: 2px solid var(--gray-300);
    border-radius: var(--radius-md);
    padding: 14px 16px;
    width: 100%;
    box-sizing: border-box;
    min-height: 96px;
    resize: vertical;
    line-height: 1.5;
}
.jml-ai-card textarea:focus { outline: none; border-color: var(--art-theme); box-shadow: var(--shadow-glow-theme); }

.jml-ai-image-row { display: flex; align-items: center; gap: var(--space-4); flex-wrap: wrap; margin-top: var(--space-4); }

.jml-ai-imgbtn {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    font-size: 17px;
    font-weight: 600;
    min-height: 48px;
    padding: 0 var(--space-5);
    border-radius: var(--radius-md);
    border: 2px solid var(--gray-300);
    background: var(--surface-card);
    color: var(--gray-700);
    cursor: pointer;
}
.jml-ai-imgbtn:hover { background: var(--surface-inset); border-color: var(--art-theme); color: var(--art-theme); }
.jml-ai-orpaste { font-size: 15px; color: var(--gray-500); }

.jml-ai-orpaste kbd {
    font-family: inherit; font-size: 13px; background: var(--surface-inset);
    border: 1px solid var(--gray-300); border-radius: var(--radius-sm); padding: 1px 6px;
}

.jml-ai-thumb-wrap { display: flex; align-items: flex-start; gap: var(--space-3); margin-top: var(--space-4); }

.jml-ai-thumb {
    max-width: 220px; max-height: 160px; border-radius: var(--radius-md);
    border: 1px solid var(--gray-300); box-shadow: var(--shadow-sm);
}

.jml-ai-thumb-clear {
    font-family: inherit; font-size: 15px; font-weight: 600;
    min-height: 40px; padding: 0 var(--space-4); cursor: pointer;
    border: 2px solid color-mix(in srgb, var(--state-danger) 35%, var(--gray-300));
    border-radius: var(--radius-md); background: var(--surface-card); color: var(--state-danger);
    display: inline-flex; align-items: center; gap: var(--space-2);
}
.jml-ai-thumb-clear:hover { background: var(--state-danger-bg); border-color: var(--state-danger); }

.jml-btn-ai {
    margin-top: var(--space-5);
    background: var(--art-theme);
    color: var(--color-on-brand);
    width: 100%;
}
.jml-btn-ai:hover { background: var(--art-theme-hover, var(--jim-mailing-list-green-dark)); }
.jml-btn-ai:disabled { opacity: .6; cursor: default; }

.jml-ai-status {
    margin: var(--space-4) 0 0;
    font-size: 17px;
    font-weight: 600;
    color: var(--state-success);
    padding: var(--space-3) var(--space-4);
    background: var(--state-success-bg);
    border-radius: var(--radius-md);
}
.jml-ai-status.is-warn { color: var(--state-warning); background: var(--state-warning-bg); }

/* ---- form fields ---- */
.jml-field { margin-bottom: var(--space-5); display: flex; flex-direction: column; }

.jml-field label {
    font-size: 18px;
    font-weight: 600;
    color: var(--gray-800);
    margin-bottom: var(--space-2);
}
.jml-opt { font-weight: 400; color: var(--gray-500); font-size: 16px; }
.jml-hint { font-size: 15px; color: var(--gray-500); margin-top: var(--space-2); }

.jml-field input,
.jml-field textarea {
    font-family: inherit;
    font-size: 19px;
    color: var(--gray-900);
    background: var(--surface-card);
    border: 2px solid var(--gray-300);
    border-radius: var(--radius-md);
    padding: 14px 16px;
    min-height: 54px;
    width: 100%;
    box-sizing: border-box;
    transition: border-color var(--dur-fast) var(--ease-out), box-shadow var(--dur-fast) var(--ease-out);
}
.jml-field textarea { min-height: 90px; resize: vertical; line-height: 1.5; }

.jml-field input:focus,
.jml-field textarea:focus,
.jml-search-wrap input:focus {
    outline: none;
    border-color: var(--art-theme);
    box-shadow: var(--shadow-glow-theme);
}

/* address + phone/email side-by-side on wide screens, stacked on phones */
.jml-row { display: flex; gap: var(--space-4); }
.jml-row .jml-field { flex: 1 1 0; }
.jml-grow { flex: 1 1 0; }
.jml-state { flex: 0 0 110px; }
.jml-zip { flex: 0 0 130px; }

/* ---- buttons ---- */
.jml-btn {
    font-family: inherit;
    font-size: 19px;
    font-weight: 600;
    min-height: 56px;
    padding: 0 var(--space-6);
    border-radius: var(--radius-md);
    border: 2px solid transparent;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-2);
    transition: background var(--dur-fast) var(--ease-out), transform var(--dur-fast) var(--ease-out);
}
.jml-btn:active { transform: translateY(1px); }

.jml-form-actions { display: flex; gap: var(--space-4); margin-top: var(--space-6); flex-wrap: wrap; }

.jml-btn-save {
    background: var(--art-theme);
    color: var(--color-on-brand);
    flex: 1 1 auto;
    min-width: 220px;
}
.jml-btn-save:hover { background: var(--art-theme-hover, var(--jim-mailing-list-green-dark)); }

.jml-btn-cancel {
    background: var(--surface-card);
    color: var(--gray-700);
    border-color: var(--gray-300);
}
.jml-btn-cancel:hover { background: var(--surface-inset); }

/* ---- list header + search ---- */
.jml-list-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-4);
    flex-wrap: wrap;
    margin-bottom: var(--space-6);
}
.jml-list-title { margin: 0; }
.jml-count { font-size: 18px; font-weight: 500; color: var(--gray-500); }

.jml-search-wrap { position: relative; flex: 0 0 300px; max-width: 100%; }

.jml-search-wrap i {
    position: absolute; left: 16px; top: 50%; transform: translateY(-50%);
    color: var(--gray-400); font-size: 17px; pointer-events: none;
}

.jml-search-wrap input {
    font-family: inherit;
    font-size: 18px;
    width: 100%;
    box-sizing: border-box;
    min-height: 52px;
    padding: 12px 16px 12px 44px;
    border: 2px solid var(--gray-300);
    border-radius: var(--radius-pill);
    background: var(--surface-card);
    color: var(--gray-900);
}

/* ---- filter bar (segment chips + sort) ---- */
.jml-filterbar { display: flex; align-items: center; justify-content: space-between; gap: var(--space-4); flex-wrap: wrap; margin-bottom: var(--space-5); }
.jml-chips { display: flex; flex-wrap: wrap; gap: var(--space-2); flex: 1 1 auto; }

.jml-chip {
    font-family: inherit; font-size: 15px; font-weight: 600;
    min-height: 40px; padding: 0 var(--space-4);
    border: 2px solid var(--gray-300); border-radius: var(--radius-pill);
    background: var(--surface-card); color: var(--gray-700);
    cursor: pointer; display: inline-flex; align-items: center; gap: var(--space-2);
}
.jml-chip:hover { border-color: var(--art-theme); color: var(--art-theme); }
.jml-chip.is-active { background: var(--art-theme); border-color: var(--art-theme); color: var(--color-on-brand); }
.jml-chip-n { font-size: 13px; font-weight: 600; background: color-mix(in srgb, currentcolor 16%, transparent); border-radius: var(--radius-pill); padding: 1px 8px; }
.jml-chip.is-active .jml-chip-n { background: rgb(255 255 255 / 28%); }

.jml-sort { font-size: 16px; color: var(--gray-600); display: inline-flex; align-items: center; gap: var(--space-2); flex: 0 0 auto; }

.jml-sort select {
    font-family: inherit; font-size: 16px; min-height: 44px; padding: 0 var(--space-3);
    border: 2px solid var(--gray-300); border-radius: var(--radius-md);
    background: var(--surface-card); color: var(--gray-900); cursor: pointer;
}
.jml-sort select:focus { outline: none; border-color: var(--art-theme); box-shadow: var(--shadow-glow-theme); }

/* ---- show more / inline link button ---- */
.jml-showmore {
    font-family: inherit; font-size: 18px; font-weight: 600;
    width: 100%; min-height: 54px; margin-top: var(--space-2);
    border: 2px dashed var(--gray-300); border-radius: var(--radius-lg);
    background: var(--surface-inset); color: var(--gray-700); cursor: pointer;
}
.jml-showmore:hover { border-color: var(--art-theme); color: var(--art-theme); }

.jml-linkbtn {
    font-family: inherit; font-size: inherit; font-weight: 600;
    background: none; border: none; color: var(--art-theme); cursor: pointer; text-decoration: underline; padding: 0;
}

/* ---- list actions (export / print labels) ---- */
.jml-list-actions { display: flex; align-items: center; gap: var(--space-3); flex-wrap: wrap; margin-bottom: var(--space-4); }

.jml-tool-btn {
    font-family: inherit; font-size: 16px; font-weight: 600;
    min-height: 46px; padding: 0 var(--space-5);
    border: 2px solid var(--gray-300); border-radius: var(--radius-md);
    background: var(--surface-card); color: var(--gray-700);
    cursor: pointer; display: inline-flex; align-items: center; gap: var(--space-2);
}
.jml-tool-btn:hover { border-color: var(--art-theme); color: var(--art-theme); }
.jml-tool-hint { font-size: 14px; color: var(--gray-500); }

/* ---- per-card outreach status ---- */
.jml-entry-status { margin-top: var(--space-3); display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }
.jml-status-label { font-size: 15px; color: var(--gray-500); font-weight: 600; }

.jml-status {
    font-family: inherit; font-size: 15px; font-weight: 600; min-height: 40px;
    padding: 0 var(--space-3); border: 2px solid var(--gray-300); border-radius: var(--radius-md);
    background: var(--surface-card); color: var(--gray-800); cursor: pointer;
}
.jml-status:focus { outline: none; border-color: var(--art-theme); box-shadow: var(--shadow-glow-theme); }
.jml-status:disabled { opacity: .6; }
.jml-lastmailed { font-size: 14px; color: var(--gray-500); }

/* status tints on the card's left edge */
.jml-entry.is-mailed { border-left: 5px solid var(--state-info); }
.jml-entry.is-responded { border-left: 5px solid var(--state-warning); }
.jml-entry.is-customer { border-left: 5px solid var(--state-success); }
.jml-entry.is-donotmail { border-left: 5px solid var(--gray-400); }

/* ---- Mailchimp card ---- */
.jml-mc-title { font-size: 22px; font-weight: 700; color: var(--gray-900); margin: 0 0 var(--space-3); display: flex; align-items: center; gap: var(--space-3); }
.jml-mc-title i { color: var(--art-theme); }
.jml-mc-help { font-size: 16px; line-height: 1.5; color: var(--gray-600); margin: 0 0 var(--space-4); }
.jml-mc-help strong { color: var(--gray-900); }
.jml-mc-actions { display: flex; gap: var(--space-3); flex-wrap: wrap; }
.jml-mc-status { margin: var(--space-4) 0 0; font-size: 16px; font-weight: 600; padding: var(--space-3) var(--space-4); border-radius: var(--radius-md); }
.jml-mc-status.is-ok { color: var(--state-success); background: var(--state-success-bg); }
.jml-mc-status.is-warn { color: var(--state-warning); background: var(--state-warning-bg); }
.jml-mc-status.is-err { color: var(--state-danger); background: var(--state-danger-bg); }

/* ---- entries ---- */
.jml-list { display: flex; flex-direction: column; gap: var(--space-4); }

.jml-entry {
    border: 1px solid var(--gray-200);
    border-radius: var(--radius-lg);
    padding: var(--space-5) var(--space-6);
    background: var(--surface-elevated);
    display: flex;
    gap: var(--space-4);
    align-items: flex-start;
    justify-content: space-between;
    flex-wrap: wrap;
}
.jml-entry-main { flex: 1 1 320px; min-width: 0; }
.jml-entry-name { font-size: 22px; font-weight: 700; color: var(--gray-900); margin: 0 0 var(--space-2); }
.jml-entry-line { font-size: 17px; color: var(--gray-700); line-height: 1.5; }
.jml-entry-line i { color: var(--gray-400); width: 22px; text-align: center; margin-right: var(--space-1); }
.jml-entry-line a { color: var(--state-info); text-decoration: none; }
.jml-entry-line a:hover { text-decoration: underline; }
.jml-entry-notes { margin-top: var(--space-2); font-size: 16px; color: var(--gray-600); font-style: italic; }
.jml-entry-source { display: inline-block; margin-top: var(--space-2); font-size: 15px; color: var(--gray-500); }

.jml-entry-cat {
    display: inline-block;
    margin-top: var(--space-2);
    margin-right: var(--space-3);
    font-size: 14px;
    font-weight: 600;
    color: var(--art-theme);
    background: var(--art-theme-light, var(--brand-100));
    border: 1px solid color-mix(in srgb, var(--art-theme) 30%, transparent);
    border-radius: var(--radius-pill);
    padding: 3px 12px;
}
.jml-entry-cat i { margin-right: 4px; }

.jml-entry-actions { display: flex; gap: var(--space-3); flex: 0 0 auto; }

.jml-mini-btn {
    font-family: inherit;
    font-size: 17px;
    font-weight: 600;
    min-height: 48px;
    padding: 0 var(--space-5);
    border-radius: var(--radius-md);
    border: 2px solid var(--gray-300);
    background: var(--surface-card);
    color: var(--gray-700);
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    transition: background var(--dur-fast) var(--ease-out), border-color var(--dur-fast) var(--ease-out);
}
.jml-mini-btn:hover { background: var(--surface-inset); }
.jml-edit:hover { border-color: var(--art-theme); color: var(--art-theme); }
.jml-delete { color: var(--state-danger); border-color: color-mix(in srgb, var(--state-danger) 35%, var(--gray-300)); }
.jml-delete:hover { background: var(--state-danger-bg); border-color: var(--state-danger); }

/* ---- empty / loading states ---- */
.jml-empty, .jml-loading {
    text-align: center;
    padding: var(--space-8) var(--space-6);
    font-size: 19px;
    color: var(--gray-500);
}
.jml-empty i { font-size: 40px; color: var(--gray-300); display: block; margin-bottom: var(--space-4); }

/* ---- highlight the form while editing ---- */
.jml-form-card.is-editing { border-color: var(--art-theme); box-shadow: var(--shadow-glow-theme), var(--shadow-md); }

/* ---- phones ---- */
@media (width <= 640px) {
    .jml-card, .jml-list-section { padding: var(--space-5); }
    .jml-row { flex-direction: column; gap: 0; }
    .jml-state, .jml-zip { flex: 1 1 auto; }
    .jml-search-wrap { flex: 1 1 100%; }
    .jml-btn-save { min-width: 0; width: 100%; }
    .jml-entry-actions { width: 100%; }
    .jml-mini-btn { flex: 1 1 0; justify-content: center; }
}

/* 2026-09-05 review — the flex wrappers (.jml-welcome, .jml-ai-thumb-wrap, .jml-filterbar, .jml-list-actions)
   BEAT the UA [hidden] rule, so the empty screenshot placeholder + Remove button showed on every load. */
/* stylelint-disable-next-line declaration-no-important -- the hidden attribute must beat any display rule */
[hidden] { display: none !important; }
.jml-visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.jml-viewbtn:focus-visible, .jml-chip:focus-visible, .jml-btn:focus-visible, .jml-tool-btn:focus-visible, .jml-linkbtn:focus-visible, .jml-ai-imgbtn:focus-visible { outline: 2px solid var(--art-theme); outline-offset: 2px; }

/* stylelint-disable no-duplicate-selectors -- legacy sheet: rules were appended over time; merging them would reorder the cascade (2026-09-07) */

/* ==========================================================================
   past-due-orders.css — page-specific styles for dashboards/past-due-orders.html

   Shell classes (.dash-header, .dash-back-link, .dash-stat-card, .dash-card…)
   come from shared_components/css/dash-shell.css. Design tokens (--surface-*,
   --gray-*, --shadow-*, --radius-*, --state-*) come from
   shared_components/css/art-hub.css.

   Only page-specific styles here. Never redefine a token, never hardcode a
   colour/shadow/radius that a token already covers.
   ========================================================================== */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue so the page
   keeps its exact look. Map them to shared_components/css/tokens.css names when the page is redesigned;
   every rule below uses var(). Raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --past-due-orders-gray-dark: #000;
    --past-due-orders-gray-dark-2: #333;
    --past-due-orders-gray: #666;
    --past-due-orders-green-dark: #0a6b2a;
}
/* stylelint-enable color-no-hex */

/* Header controls -------------------------------------------------------- */

/* These labels sit ON the green header, not on the page surface — --gray-600 is a
   dark grey that all but disappears against it. White at 88% reads clearly while
   staying subordinate to the solid-white control text beside it. */
.pdo-window {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 0.85rem;
    color: rgb(255 255 255 / 88%);
}

.pdo-window select {
    font: inherit;
    padding: 4px 8px;
    border: 1px solid var(--gray-300);
    border-radius: var(--radius-sm);
    background: var(--surface-card, var(--color-surface));
    color: var(--gray-800);
}

/* Rep options carry their counts ("Nika Lao (14 past due · 9 at risk)"), which is long
   enough to push the Dashboard link off the header without a ceiling. */
.pdo-printfor select {
    max-width: 15rem;
}

/* Both print controls sit disabled until a load succeeds — they have to LOOK inert,
   or a click that deliberately does nothing reads as a broken button. The button half
   of this now lives on .dash-back-link:disabled in dash-shell.css. */
.pdo-printfor select:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.pdo-asof {
    font-size: 0.8rem;
    color: var(--gray-500);
}

/* Per-rep grouping ------------------------------------------------------- */
.pdo-rep {
    margin-bottom: 28px;
}

.pdo-rep-name {
    display: flex;
    align-items: baseline;
    gap: 12px;
    margin: 0 0 8px;
    font-size: 1rem;
    font-weight: 700;
    color: var(--gray-800);
}

.pdo-rep-count {
    font-size: 0.8rem;
    font-weight: 500;
    color: var(--gray-500);
}

/* Table ------------------------------------------------------------------ */

/* Wide content scrolls inside its own container so the page body never does. */
.pdo-scroll {
    overflow-x: auto;
}

.pdo-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.85rem;
}

.pdo-table th {
    text-align: left;
    padding: 6px 10px;
    border-bottom: 2px solid var(--gray-200);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: var(--gray-500);
    white-space: nowrap;
}

.pdo-table td {
    padding: 7px 10px;
    border-bottom: 1px solid var(--gray-100);
    color: var(--gray-800);
    vertical-align: top;
}

.pdo-table tbody tr:hover {
    background: var(--gray-50);
}

.pdo-num {
    text-align: right;
    white-space: nowrap;
}

.pdo-wo {
    font-family: 'JetBrains Mono', ui-monospace, monospace;
    white-space: nowrap;
}

/* A past-due row must not rely on colour alone — the weight carries it in
   greyscale and for anyone who can't distinguish the red. */
.pdo-late .pdo-wo,
.pdo-late td:nth-child(2) {
    font-weight: 700;
}

.pdo-badge {
    display: inline-block;
    padding: 1px 7px;
    border-radius: var(--radius-sm);
    background: var(--state-danger-bg, var(--red-100));
    color: var(--state-danger-fg, var(--red-800));
    font-weight: 700;
    font-size: 0.78rem;
    white-space: nowrap;
}

.pdo-risk {
    color: var(--gray-600);
}

/* The single most actionable cell on the page: more than half of past-due
   orders are waiting on blanks nobody has ordered yet. */
.pdo-nopo {
    font-weight: 700;
    color: var(--state-danger-fg, var(--red-800));
}

/* States ----------------------------------------------------------------- */
.pdo-none {
    padding: 18px;
    color: var(--gray-600);
}

.pdo-none i {
    color: var(--state-success-fg, var(--green-700));
    margin-right: 6px;
}

.pdo-trunc,
.pdo-failed {
    padding: 12px 14px;
    margin-bottom: 14px;
    border-radius: var(--radius-md);
    background: var(--state-warning-bg, var(--amber-100));
    color: var(--state-warning-fg, var(--amber-800));
    font-size: 0.85rem;
}

/* Printed rep sheets ------------------------------------------------------ */

/* Erik prints these at 8am and hands each rep their page. The sheet is built into
   #pdo-print-sheet by the controller and everything else on the page is hidden —
   the same isolation the SanMar inbound sheets use (sanmar-inbound.css:291), and
   the reason the printout no longer carries the stat tiles or the header controls. */
#pdo-print-sheet {
    display: none;
}

@media print {
    body.pdo-printing > *:not(#pdo-print-sheet) {
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        display: none !important;
    }

    body.pdo-printing #pdo-print-sheet {
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        display: block !important;
    }

    @page {
        size: letter portrait;
        margin: 0.5in;
    }

    /* Last-resort fallback: a keyboard print that could NOT build a sheet (no data loaded
       yet) still lands here. The controller's beforeprint handler covers the normal case;
       without these the board would print as the raw 4-page blob the sheets replaced,
       which would be a regression on the old behaviour rather than an improvement. */
    body:not(.pdo-printing) .dash-header-right,
    body:not(.pdo-printing) .dash-error-banner,
    body:not(.pdo-printing) .dash-stat-grid {
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        display: none !important;
    }

    body:not(.pdo-printing) .pdo-rep {
        break-inside: avoid;
    }

    body:not(.pdo-printing) .pdo-table tbody tr {
        break-inside: avoid;
    }

    body:not(.pdo-printing) .pdo-badge {
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        background: var(--past-due-orders-gray-dark) !important;
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        color: var(--color-on-brand) !important;
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }

    body:not(.pdo-printing) .pdo-nopo {
        /* stylelint-disable-next-line declaration-no-important -- legacy: outranks a higher-specificity rule — re-examine when this page is redesigned */
        color: var(--past-due-orders-gray-dark) !important;
        font-weight: 900;
    }
}

/* Sheet body. Fixed px sizes, not tokens: this is paper, where a rem that follows
   the browser's font setting would change how many rows land on a page. */
#pdo-print-sheet {
    color: var(--print-ink);
    font-family: Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    font-size: 9.5px;
    line-height: 1.3;
}

/* One rep per PAGE. The first section never breaks, so a run doesn't lead with a
   blank sheet — and a single-rep print is exactly one page. */
.pdo-ps-brk {
    break-before: page;
}

/* table-layout: fixed is what stops the wrapping. Without it the browser sized
   columns to content and split dates across two lines ("2026-" / "07-31"). */
.pdo-ps-tbl {
    width: 100%;
    table-layout: fixed;
    border-collapse: collapse;
    margin-bottom: 14px;
}

/* Reprints the rep's name and the column headers at the top of every physical page
   the table spills onto. This is the fix for the orphan page that belonged to nobody. */
.pdo-ps-tbl thead {
    display: table-header-group;
}

.pdo-ps-tbl tbody tr {
    break-inside: avoid;
}

/* Header rows ------------------------------------------------------------- */
.pdo-ps-banner th {
    text-align: left;
    padding: 0 0 5px;
    border-bottom: 2px solid var(--print-green);
    font-weight: 400;
}

.pdo-ps-brand {
    font-size: 10px;
    font-weight: 800;
    color: var(--print-green);
    letter-spacing: 0.02em;
}

.pdo-ps-repname {
    font-size: 19px;
    font-weight: 800;
    color: var(--print-ink);
    line-height: 1.15;
    margin-top: 1px;
}

/* The continued/second-section banner — smaller, because the full brand block has
   already appeared above it on the same sheet. */
.pdo-ps-repname--cont {
    font-size: 12px;
    color: var(--gray-700);
}

.pdo-ps-sub {
    font-size: 10px;
    color: var(--gray-700);
    margin-top: 2px;
}

/* The scope disclaimer. Small, but it is the difference between "your past-due list" and
   "your past-due list for the last 30 days" — a rep who reads the first will close an
   older order out of their head. */
.pdo-ps-note {
    font-size: 8.5px;
    color: var(--past-due-orders-gray);
    margin-top: 2px;
}

.pdo-ps-sect th {
    text-align: left;
    padding: 9px 0 3px;
    font-size: 10.5px;
    font-weight: 800;
    color: var(--print-green);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.pdo-ps-sect-n {
    float: right;
    font-weight: 600;
    text-transform: none;
    letter-spacing: 0;
    color: var(--print-ink-soft);
}

.pdo-ps-cols th {
    text-align: left;
    padding: 3px 5px;
    border-top: 1px solid var(--print-green);
    border-bottom: 1px solid var(--print-green);
    font-size: 8.5px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: var(--past-due-orders-gray-dark-2);
}

/* `.pdo-ps-cols th` outranks the bare alignment classes, so the numeric headers need
   to be named here or they sit left of the figures they label. */
.pdo-ps-cols th.pdo-ps-c   { text-align: center; }
.pdo-ps-cols th.pdo-ps-val { text-align: right; }

/* Column widths sum to 100% of the 7.5in text block, sized so that no ordinary value
   wraps: "Asphalt Patch Systems Inc.", "Custom Embroidery", "ordered, not in" and a
   6-figure WO all fit on one line. Customer keeps the slack — a genuinely long name
   is the only cell allowed to run to two lines.

   These live on <col>, not on the <th>: under table-layout:fixed the browser reads
   column widths from the first row, which is the full-width banner. */
.pdo-ps-w-wo    { width: 8%; }
.pdo-ps-w-cust  { width: 26%; }
.pdo-ps-w-type  { width: 14.5%; }
.pdo-ps-w-date  { width: 8.5%; }
.pdo-ps-w-late  { width: 7%; }
.pdo-ps-w-val   { width: 9.5%; }
.pdo-ps-w-blank { width: 18%; }

/* Body rows --------------------------------------------------------------- */
.pdo-ps-tbl td {
    padding: 3.5px 5px;
    border-bottom: 1px solid var(--store-line);
    vertical-align: top;
    overflow-wrap: break-word;
}

.pdo-ps-wo {
    font-family: 'JetBrains Mono', ui-monospace, monospace;
    font-weight: 700;
    white-space: nowrap;
}

.pdo-ps-cust {
    font-weight: 700;
}

.pdo-ps-nowrap { white-space: nowrap; }
.pdo-ps-c      { text-align: center; white-space: nowrap; }

.pdo-ps-val {
    text-align: right;
    white-space: nowrap;
    font-variant-numeric: tabular-nums;
}

/* The date the rep is here to change — the one cell the whole sheet exists for. */
.pdo-ps-due {
    font-weight: 800;
}

/* At-risk rows are context, not the job. Greyed so the past-due list stays dominant. */
.pdo-ps-risk td {
    color: var(--print-ink-soft);
}

.pdo-ps-risk .pdo-ps-cust,
.pdo-ps-risk .pdo-ps-wo {
    font-weight: 600;
}

.pdo-ps-vendor {
    display: block;
    font-size: 8.5px;
    color: var(--print-ink-soft);
}

.pdo-ps-tot td {
    border-top: 1.5px solid var(--print-green);
    border-bottom: none;
    padding-top: 4px;
    font-weight: 800;
    color: var(--past-due-orders-gray-dark-2);
}

/* Mono laser: it drops backgrounds unless told otherwise, so a tinted badge would
   print as an unreadable grey smudge and "no PO raised" would lose its red entirely.
   Both are forced to black — weight and reverse carry the signal in greyscale. */
.pdo-ps-badge {
    display: inline-block;
    padding: 0 5px;
    border-radius: 2px;
    background: var(--past-due-orders-gray-dark);
    color: var(--color-on-brand);
    font-weight: 800;
    white-space: nowrap;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

.pdo-ps-nopo {
    font-weight: 900;
    color: var(--past-due-orders-gray-dark);
}

/* ==========================================================================
   2026-09-04 review additions
   ========================================================================== */

/* Stat tiles: dollar value under the count. */
.pdo-stat-sub {
    margin-top: 4px;
    font-size: 0.78rem;
    color: var(--gray-500);
    min-height: 1.1em;
}

/* Board summary ("52 orders on the board · 4 reps · as of …"). */
.pdo-asof #pdo-summary { color: var(--gray-700); font-weight: 600; }

/* Rep heading → the rep's account page. */
.pdo-rep-link {
    color: inherit;
    text-decoration: none;
    border-bottom: 1px dashed var(--gray-300);
}
.pdo-rep-link:hover { color: var(--nw-green, var(--past-due-orders-green-dark)); border-bottom-color: currentcolor; }
.pdo-rep-link i { font-size: 0.7em; opacity: 0.6; margin-left: 2px; }

.pdo-rep-total {
    margin-left: auto;
    font-family: 'JetBrains Mono', ui-monospace, monospace;
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--gray-700);
}

/* "no PO raised" → Purchase Request form. Keeps the danger colour and adds the affordance. */
.pdo-nopo-link { color: inherit; text-decoration: none; border-bottom: 1px dashed currentcolor; white-space: nowrap; }
.pdo-nopo-link:hover { text-decoration: none; opacity: 0.8; }
.pdo-nopo-link i { font-size: 0.85em; margin-left: 3px; }

/* Vendor to chase, under the blanks status (the printed sheet always had it). */
.pdo-vendor { display: block; font-size: 0.75rem; color: var(--gray-500); }

.pdo-partial {
    display: inline-block; margin-left: 6px; padding: 0 6px; border-radius: var(--radius-sm);
    font-size: 0.7rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.03em;
    background: var(--state-warning-bg, var(--amber-100)); color: var(--state-warning-fg, var(--amber-800));
}

.pdo-dash { color: var(--gray-300); }

/* Phones: the header control row was 781px wide at 375px and scrolled the whole page
   sideways. Wrap the controls onto their own full-width rows. */
@media (width <= 760px) {
    .dash-header-right {
        width: 100%;
        flex-wrap: wrap;
        gap: 8px;
    }
    .pdo-window { flex: 1 1 100%; justify-content: space-between; }
    .pdo-window select { flex: 1; max-width: none; }
    .pdo-printfor select { max-width: none; }
    .dash-header-right .dash-back-link { flex: 1 1 auto; justify-content: center; }
    .pdo-rep-name { flex-wrap: wrap; }
}

/* ==========================================================================
