   Only page-specific styles here — never redefine tokens or hardcode
   colors/shadows/radii.
   ========================================================================== */

.pm-subtitle {
    font-size: 0.75em;
    font-weight: 500;
    color: var(--gray-500);
    margin-left: 8px;
}

.pm-header-actions { display: flex; gap: 10px; align-items: center; }

.pm-filter {
    font: inherit; font-size: 13.5px;
    padding: 7px 12px;
    border: 1px solid var(--gray-300);
    border-radius: var(--radius-md);
    min-width: 240px;
}

.pm-help {
    font-size: 13px;
    color: var(--gray-600);
    background: var(--gray-50);
    border: 1px solid var(--gray-200);
    border-radius: var(--radius-md);
    padding: 10px 14px;
    margin: 0 0 14px;
}

/* Buttons */
.pm-btn {
    display: inline-flex; align-items: center; gap: 6px;
    font: inherit; font-size: 13px; font-weight: 600;
    padding: 7px 14px;
    border-radius: var(--radius-md);
