    background: var(--surface-card, var(--color-surface));
    color: var(--gray-700);
    cursor: pointer;
    text-decoration: none;
}
.pm-btn:hover { border-color: var(--gray-400); }

.pm-btn-primary {
    background: var(--state-success, var(--store-green-700));
    border-color: var(--state-success, var(--store-green-700));
    color: var(--color-on-brand);
}
.pm-btn-primary:hover:not(:disabled) { filter: brightness(1.08); }
.pm-btn-primary:disabled { opacity: 0.65; cursor: wait; }
.pm-btn-ghost { background: transparent; }

/* Table */
.pm-table-wrap { overflow-x: auto; }
.pm-table { width: 100%; border-collapse: collapse; font-size: 13.5px; }

.pm-table th {
    text-align: left; font-size: 11px; font-weight: 700;
    letter-spacing: 0.06em; text-transform: uppercase;
    color: var(--gray-500);
    padding: 8px 10px;
    border-bottom: 1px solid var(--gray-200);
}

.pm-table td {
    padding: 8px 10px;
    border-bottom: 1px solid var(--gray-100);
    vertical-align: middle;
}
.pm-num { text-align: right; }
.pm-style { font-family: 'JetBrains Mono', monospace; font-size: 12.5px; font-weight: 600; }
.pm-row-inactive td { opacity: 0.55; }
.pm-warn-text { color: var(--state-warning, var(--amber-700)); font-weight: 600; }

.pm-thumb {
    width: 44px; height: 44px;
    object-fit: contain;
    border: 1px solid var(--gray-200);
    border-radius: var(--radius-sm);
    background: var(--gray-50);
    display: inline-flex; align-items: center; justify-content: center;
    color: var(--gray-300);
}
.pm-thumb-empty { font-size: 16px; }

.pm-chip {
    display: inline-block;
    font-size: 11px; font-weight: 700;
    padding: 2px 10px;
    border-radius: 999px;
    background: var(--gray-100);
    color: var(--gray-600);
}
.pm-chip-live { background: var(--state-success-bg, var(--store-green-100)); color: var(--state-success, var(--store-green-700)); }

.pm-actions { white-space: nowrap; text-align: right; }
.pm-empty { color: var(--gray-500); font-size: 14px; padding: 18px 4px; }

/* Form */
.pm-form-card { margin-top: 16px; }

.pm-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px 18px;
}
.pm-span-2 { grid-column: span 2; }
.pm-field { display: flex; flex-direction: column; gap: 4px; }
.pm-field label { font-size: 12.5px; font-weight: 700; color: var(--gray-600); }
.pm-field small { font-size: 11.5px; color: var(--gray-500); }
.pm-req { color: var(--state-danger, var(--red-700)); }

.pm-field input[type="text"],
.pm-field input[type="number"],
.pm-field input[type="url"],
.pm-field select,
.pm-field textarea {
    font: inherit; font-size: 14px;
    padding: 8px 11px;
    border: 1px solid var(--gray-300);
    border-radius: var(--radius-md);
    width: 100%;
}
.pm-field input:disabled { background: var(--gray-100); color: var(--gray-500); }

.pm-image-row { display: flex; gap: 14px; align-items: flex-start; }

.pm-image-preview {
    width: 84px; height: 84px;
    object-fit: contain;
    border: 1px solid var(--gray-200);
    border-radius: var(--radius-md);
    background: var(--gray-50);
    flex: none;
}
.pm-image-controls { display: flex; flex-direction: column; gap: 6px; flex: 1; }

.pm-form-actions {
    display: flex; align-items: center; gap: 18px;
    margin-top: 18px;
    padding-top: 14px;
    border-top: 1px solid var(--gray-200);
}

.pm-active-toggle {
    display: flex; align-items: center; gap: 8px;
    font-size: 13.5px; font-weight: 600; color: var(--gray-700);
    cursor: pointer;
}
.pm-active-toggle input { width: 16px; height: 16px; accent-color: var(--state-success, var(--store-green-700)); }

@media (width <= 720px) {
    .pm-grid { grid-template-columns: 1fr; }
    .pm-span-2 { grid-column: span 1; }
    .pm-header-actions { flex-wrap: wrap; }
}

/* 2026-09-05 review */
/* stylelint-disable-next-line declaration-no-important -- the hidden attribute must beat any display rule */
