/* ==========================================================================
   volume-quote.css — page-specific styles for dashboards/volume-quote.html

   Shell classes (.dash-header, .dash-back-link, .dash-stat-card, etc.) come
   from shared_components/css/dash-shell.css. Design tokens (--surface-*,
   --gray-*, --shadow-*, --radius-*, --state-*) come from
   shared_components/css/art-hub.css.

   Only page-specific styles here. NEVER redefine tokens. NEVER hardcode
   colors/shadows/radii — use var(--token-name).
   ========================================================================== */

.vq-intro { color: var(--gray-600); margin: 0 0 1rem; max-width: 70ch; }

.vq-step {
    display: inline-flex; align-items: center; justify-content: center;
    width: 1.6em; height: 1.6em; margin-right: .4em;
    border-radius: var(--radius-pill); background: var(--gray-800); color: var(--surface-card);
    font-size: .8em; font-weight: 600;
}

/* ── form ─────────────────────────────────────────────────────────────── */
.vq-form-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: .9rem; }
.vq-field { display: flex; flex-direction: column; gap: .3rem; font-size: .85rem; color: var(--gray-600); }

.vq-field input, .vq-field select, .vq-lever input[type="number"], .vq-line input {
    font: inherit; padding: .5rem .6rem; border: 1px solid var(--gray-300);
    border-radius: var(--radius-md); background: var(--surface-card); color: var(--gray-900);
}
.vq-field input:focus, .vq-field select:focus, .vq-line input:focus, .vq-lever input:focus { outline: 2px solid var(--state-info); outline-offset: 1px; }
.vq-field--check { flex-direction: row; align-items: center; gap: .5rem; align-self: end; padding-bottom: .5rem; }
.vq-field--check input { width: 1.1rem; height: 1.1rem; }

/* ── garment lines ─────────────────────────────────────────────────────── */
.vq-lines-head, .vq-line {
    display: grid; grid-template-columns: 120px 90px 1.6fr 1.2fr 1fr 40px;
    gap: .6rem; align-items: center;
}
.vq-lines-head { font-size: .75rem; text-transform: uppercase; letter-spacing: .04em; color: var(--gray-500); padding: 0 0 .4rem; border-bottom: 1px solid var(--gray-200); }
.vq-line { padding: .5rem 0; border-bottom: 1px solid var(--gray-100); font-size: .9rem; }
.vq-line-title { color: var(--gray-800); }
.vq-line-title small { display: block; color: var(--gray-500); }
.vq-line-cost { font-family: 'JetBrains Mono', monospace; font-size: .85rem; }
.vq-line-cost small { color: var(--gray-500); }
.vq-line-stock { font-size: .8rem; color: var(--gray-600); }
.vq-line-status { font-size: .8rem; color: var(--gray-500); }
.vq-line-status--error { color: var(--state-danger); }
.vq-line-remove { border: 0; background: transparent; color: var(--gray-400); cursor: pointer; font-size: 1rem; }
.vq-line-remove:hover { color: var(--state-danger); }
.vq-hint { font-size: .8rem; color: var(--gray-500); margin: .8rem 0 0; max-width: 80ch; }

/* ── levers ────────────────────────────────────────────────────────────── */
.vq-levers { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 1rem; }
.vq-lever label { display: block; font-size: .85rem; color: var(--gray-600); margin-bottom: .35rem; }
.vq-lever-row { display: flex; align-items: center; gap: .75rem; }
