.vq-lever output { font-family: 'JetBrains Mono', monospace; font-weight: 600; min-width: 3ch; }
.vq-lever-note { font-size: .8rem; color: var(--gray-500); }

/* ── result ────────────────────────────────────────────────────────────── */
.vq-stats { margin-bottom: 1rem; }
.vq-warnings:empty { display: none; }

.vq-warning {
    padding: .6rem .8rem; margin-bottom: .6rem; border-radius: var(--radius-md);
