.vq-table tfoot td { font-weight: 600; background: var(--surface-inset); }
.vq-gm-low { color: var(--state-danger); }

/* ── memo ──────────────────────────────────────────────────────────────── */
.vq-memo-actions { display: flex; gap: .5rem; }

.vq-memo {
