@media (width <= 640px) {
    /* .vq-table already sits in .vq-table-wrap; the customer-quote table did not. */
    .vq-cq-table { display: block; overflow-x: auto; -webkit-overflow-scrolling: touch; }
}

@media (width <= 640px) {
    /* Line rows are a 6-column grid sized for a desk; on a phone let the cells wrap. */
    .vq-lines-head { display: none; }
    .vq-line { display: flex; flex-wrap: wrap; gap: .4rem .6rem; }
    .vq-line > * { min-width: 0; }
    .vq-line-info { flex: 1 1 100%; }
}

/* 2026-09-05 review */
/* stylelint-disable-next-line declaration-no-important -- the hidden attribute must beat any display rule */
[hidden] { display: none !important; }
